// دالة تجهيز صفوف إدخال أوزان الـ FOD لمواقع المهبط
function generateFodInputRows(){const m=document.getElementById('fodInputMonth').value;if(!m)return alert("برجاء اختيار الشهر أولاً");document.getElementById('fodForm').style.display='block';const tb=document.getElementById('fod-input-tbody');tb.innerHTML='';fodLocations.forEach((item,idx)=>{tb.innerHTML+=`<tr><td><input type="date" id="fod_date_${idx}" required style="width:100%;"></td><td><b>${item.loc}</b></td><td>${item.area}</td><td><input type="number" step="0.001" id="fod_p_${idx}" required style="width:100%;"></td><td><input type="number" step="0.001" id="fod_m_${idx}" required style="width:100%;"></td></tr>`;});}

// دالة حفظ كميات الـ FOD المجمعة في السيرفر
async function submitFOD(e){if(e)e.preventDefault();const btn=document.getElementById('submitFodBtn'),msg=document.getElementById('fodMsg');if(btn){btn.disabled=true;btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> جاري الإرسال...';}let arr=[],lArr=[];fodLocations.forEach((item,idx)=>{let d=document.getElementById(`fod_date_${idx}`)?.value||new Date().toISOString().split('T')[0],p=parseFloat(document.getElementById(`fod_p_${idx}`)?.value)||0,m=parseFloat(document.getElementById(`fod_m_${idx}`)?.value)||0,nId="FOD-"+Date.now()+"-"+idx;arr.push({id:nId,date:d,location:item.loc,area:item.area,plastic:p,metal:m});lArr.push({ID:nId,Date:d,Location:item.loc,Area:item.area,Plastic:p,Metal:m});});safePost({action:"submitBulkFOD",fodDataArray:arr},btn,msg,"تم الحفظ بنجاح!",()=>{globalFod=[...globalFod,...lArr];setTimeout(()=>{document.getElementById('fodForm').style.display='none';},1500);});}

// دالة توليد تقرير أوزان الـ FOD الشهري للطباعة
function generateFodPrintReport(){const m=document.getElementById('fodReportMonth').value;if(!m)return alert("برجاء اختيار الشهر أولاً لعرض التقرير");let flt=globalFod.filter(f=>{let rd=f.Date||f.date||'';if(!rd)return false;return(typeof rd==='string'?rd:new Date(rd).toISOString()).split('T')[0].startsWith(m);});const tb=document.getElementById('fod-print-tbody');if(!tb)return;tb.innerHTML='';let tp=0,tm=0;fodLocations.forEach(loc=>{let rc=flt.find(f=>(f.Location||f.location)===loc.loc),p=rc?parseFloat(rc.Plastic||rc.plastic||0):0,met=rc?parseFloat(rc.Metal||rc.metal||0):0;tp+=p;tm+=met;let dD=rc?String(rc.Date||rc.date).split('T')[0]:'---';tb.innerHTML+=`<tr><td style="border:1px solid #777;padding:12px;">${dD}</td><td style="border:1px solid #777;padding:12px;font-weight:bold;">${loc.loc}</td><td style="border:1px solid #777;padding:12px;">${loc.area}</td><td style="border:1px solid #777;padding:12px;">${p>0?p.toFixed(3)+' kg':'---'}</td><td style="border:1px solid #777;padding:12px;">${met>0?met.toFixed(3)+' kg':'---'}</td><td style="border:1px solid #777;padding:12px;">---</td></tr>`;});tb.innerHTML+=`<tr style="background:#fafafa;font-weight:bold;"><td colspan="3" style="border:1px solid #777;padding:12px;">الإجمالي</td><td style="border:1px solid #777;padding:12px;">${tp.toFixed(3)} kg</td><td style="border:1px solid #777;padding:12px;">${tm.toFixed(3)} kg</td><td style="border:1px solid #777;padding:12px;color:#003366;">${(tp+tm).toFixed(3)} kg</td></tr>`;document.getElementById('printable-fod-report').style.display='block';}

// دالة تصدير تقرير الـ FOD إلى ملف PDF
