// دالة تنسيق فروق مؤشرات الأداء والأسهم
function formatTrendDifference(dV,iHb,un=""){let n=parseFloat(dV);if(isNaN(n)||n===0)return`<span style="color:#6c757d;font-weight:bold;">0 ${un} <i class="fa-solid fa-arrows-left-right"></i></span>`;let iP=n>0,fV=Math.abs(n).toFixed(un.includes("كجم")?3:0),iG=iHb?iP:!iP,clr=iG?"#28a745":"#dc3545",aI=iP?"fa-arrow-up":"fa-arrow-down";return`<span style="color:${clr};font-weight:bold;direction:ltr;display:inline-flex;align-items:center;gap:4px;">${fV} ${un} <i class="fa-solid ${aI}"></i></span>`;}

// دالة حساب الشهر السابق
function getPreviousMonthStr(ms){if(!ms)return'';let p=ms.split('-');let y=parseInt(p[0]),m=parseInt(p[1]);let d=new Date(y,m-2,1);return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;}

// دالة تجميع إحصائيات التقرير الشهري الشامل
function getMonthlyDetailedStats(ms){let p=(ms||'').split('-'),y=p[0]||'',m=p[1]||'',mN=parseInt(m||'0').toString(),s={ms:ms,mov:0,acc:0,inc:0,fT:0,fO:0,fC:0,surv:[],fTot:0,incList:[],fDept:{}};if(globalSpiData){let sR=globalSpiData.find(r=>String(r.Year)===String(y)&&String(r.Month)===mN&&r.Indicator_Name==="OperationalSPI");if(sR){try{s.mov=parseInt(JSON.parse(sR.Actual_Value).Movements)||0;}catch(e){}}}if(globalIncidents){globalIncidents.forEach(i=>{let idt=i.Date?String(i.Date).split('T')[0]:'';if(idt.startsWith(ms)){if(i.Risk_Severity==='Catastrophic')s.acc++;else s.inc++;s.incList.push(i);}});}if(globalDailyInspections){globalDailyInspections.forEach(d=>{let ddt=d.date?String(d.date).split('T')[0]:'';if(ddt.startsWith(ms)&&d.findings){d.findings.forEach(f=>{s.fT++;if(f.status==='مغلق')s.fC++;else s.fO++;let resp=f.responsible||f.Responsible||'أخرى';s.fDept[resp]=(s.fDept[resp]||0)+1;});}});}if(globalSurveys){globalSurveys.forEach(sv=>{let sdt=sv.Date?String(sv.Date).split('T')[0]:'';if(sdt.startsWith(ms))s.surv.push(sv);});}if(globalFod){globalFod.forEach(f=>{let rd=f.Date||f.date||'',fdt=(typeof rd==='string'?rd:new Date(rd).toISOString()).split('T')[0];if(fdt.startsWith(ms)){s.fTot+=(parseFloat(f.Plastic||f.plastic||0)+parseFloat(f.Metal||f.metal||0));}});}return s;}

// دالة إصدار التقرير الشهري المعتمد بالعناوين العربية وتصميم الغلاف العريض وبدون ذكر المعدة في الحصر
